  str_n29_detective_clue_name_28 = "การแทน",
  str_n29_detective_clue_name_29 = "ทะเบียนอีก",
  str_n29_detective_clue_name_30 = "หนังสือสคริปต์สกปรก",
  str_n29_detective_clue_name_31 = "ขวาน",
  str_n29_detective_clue_name_32 = "หลงทาง",
  str_n29_detective_clue_name_33 = "เรื่องสำคัญ",
  str_n29_detective_clue_desc_1 = "ฮาติได้ยินเสียงแปลกๆ 2 เสียงคุยกันเมื่อเธอครึ่งหลับครึ่งตื่น\nพวกเขาบอกว่าเธอเป็นเด็กสันโดษ มีนิสัยดื้อรั้นและไม่เข้ากับคนง่ายซึ่งคนส่วนใหญ่ไม่ชอบ\nพวกเขายังบอกว่าเธอแข็งแกร่งเกินไปและควบคุมตัวเองไม่ได้ และเธอมักจะจุดไฟเผา\nไม่มีใครต้องการเด็กเช่นนี้",
  str_n29_detective_clue_desc_2 = "เด็กที่ไม่เป็นที่นิยมเรียกว่า \"เด็กเหลือขอ\" ในสถานเลี้ยงเด็กกำพร้า\nพวกเขาบอกว่าไม่มีประโยชน์ที่จะรั้งเด็กเหล่านี้ไว้ และถึงเวลาแล้วที่จะต้องส่งฮาติไป",
  str_n29_detective_clue_desc_3 = "Miss Childminder บอก Hati ว่าสถานเลี้ยงเด็กกำพร้าคือบ้านใหม่ของเธอ\nแม่ของเธอไม่สามารถอยู่กับเธอได้ในตอนนี้... แต่ Miss Childminder ทำได้\nมีเด็กน่ารักมากมายที่นี่ และ Miss Childminder คิดว่า Hati จะสามารถใช้ชีวิตร่วมกับทุกคนได้อย่างมีความสุข",
  str_n29_detective_clue_desc_4 = "คนทำความสะอาดบอกฮาติว่าสถานเลี้ยงเด็กกำพร้าเป็นสถานที่รับเด็กที่ไม่พึงประสงค์\nและแม่ของฮาติทิ้งเธอไว้ที่นี่ คงเป็นเพราะเกลียดเธอ\nไม่มีใครสนใจเด็กที่ไม่มีพ่อแม่ พวกเขาเป็นเหมือนก้อนหินข้างถนนและผู้คนก็เตะพวกเขาออกไปให้พ้นทาง\nจากนี้ไป สิ่งที่อยู่ข้างหน้า Hati คือชีวิตที่อาศัยอยู่ในนรกตลอดเวลา",
  str_n29_detective_clue_desc_5 = "ถุงมือที่ดูคุ้นตาเหล่านี้เปียกน้ำบนพื้นผิว\nHati เคยเห็นถุงมือแบบนี้มาก่อน แม่ของเธอสวมถุงมือแบบเดียวกันเมื่อทำความสะอาด\nฮาติจำได้ว่าแม่ของเธอบอกว่าถุงมือทำให้อะไรๆ ง่ายขึ้น",
  str_n29_detective_clue_desc_6 = "ขนมปังถุงเล็ก\nดูเหมือนว่ามีน้ำเข้าไปข้างใน และตอนนี้ขนมปังก็แฉะไปหมดและมีกลิ่นอับ\nHati กล่าวว่าขนมปังที่แม่ของเธอทำให้เธอมีกลิ่นหอมและนุ่มมาก\nเหมือนคิดถึงแม่...",
  str_n29_detective_clue_desc_7 = "ผู้หญิงคนนั้นบอกว่าเธอมีเพื่อนตัวน้อยที่สนุกสนานมากมายในสถานเลี้ยงเด็กกำพร้า\nทุกคนเล่นของเล่น วาดรูป กิน และนอนด้วยกันทุกวัน ที่นี่ไม่เคยเบื่อ!\nแต่ก็มีเด็กเลวๆ อยู่ด้วย... มันจะดีกว่าถ้าฮาติอยู่ห่างจากพวกเขา",
  str_n29_detective_clue_desc_8 = "คุณรู้หรือไม่ว่า \"เปี๊ยก\" คืออะไร?\nเป็นเด็กที่ไม่มีใครชอบ\nเช่นเดียวกับราชาผู้ชั่วร้าย ใครๆ ก็คิดว่าเขาปวดหลังมาก และไม้แขวนเล็กๆ ที่ลื่นไหลของเขาก็เช่นกัน!\nแต่ไม่มีใครกลัวเด็กเหลือขอเหล่านั้น เพราะทุกคนรู้ว่าเด็กเหลือขอได้รับในสิ่งที่พวกเขาสมควรได้รับ\nเด็กดีได้ขนม เด็กเลวโดนทำโทษ ผู้หญิงคนนั้นบอกว่าเป็นเช่นนี้เสมอในสถานเลี้ยงเด็กกำพร้า",
  str_n29_detective_clue_desc_9 = "การแขวนคอนั้นชอบที่จะอาศัยอยู่ในสถานเลี้ยงเด็กกำพร้าจริงๆ\nท่านผู้อำนวยการผู้ยิ่งใหญ่และเปี่ยมด้วยเมตตา ความเมตตาของท่านทำให้เด็กจรจัดได้รับการดูแลและความอบอุ่นเหมือนครอบครัว!\nแต่ความสุขนี้หายวับไป\nเด็กที่ดีที่สุดจะถูกส่งไปยังครอบครัวที่ร่ำรวยทุกเดือนเพื่อมีชีวิตที่ไร้กังวล เด็กที่น่าสยดสยองถูกส่งไปยังครอบครัวที่ยากจนซึ่งไม่มีใครสนใจพวกเขาจริงๆ\nแต่ไม่เป็นไร ไม้แขวนเสื้อนั่นยังมีมนต์ลับของเขาอยู่ ตราบใดที่คุณยังคงประจบประแจงผู้ใหญ่ แม้ว่าพวกเขาจะไม่ชอบคุณจริงๆ อย่างน้อยพวกเขาก็จะปล่อยให้คุณอยู่คนเดียวสักพัก",
  str_n29_detective_clue_desc_10 = "ราชาผู้ชั่วร้ายบอกว่าเขาเป็นตัวละครหลักของสถานเลี้ยงเด็กกำพร้า!\nเขาดังที่สุด ใครๆ ก็ต้องสนใจเขา และของเล่นทั้งหมดก็เป็นของเขาด้วย!\nดูสิ เขาได้รับเลือกให้รับบทนำในละครคืนพรุ่งนี้ด้วยซ้ำ... ก็เป็นเรื่องธรรมดา เพราะเขาคือคนเดียวที่สำคัญในที่นี้!\nสำหรับเด็กผู้หญิงที่น่ารักและผู้ใหญ่ที่อยู่บนเวทีกับเขา พวกเขาเป็นเพียงอุปกรณ์ประกอบฉากเพื่อทำให้ตัวละครหลักโดดเด่นยิ่งขึ้น\nแต่ผู้หญิงคนนั้นดังกว่า The Wicked King... และเขาทนไม่ได้!",
  str_n29_detective_clue_desc_11 = "Miss Childminder กล่าวว่าผู้ใหญ่ชอบเด็กที่มีเหตุผล\nตราบใดที่ฮาติช่วยเหลือผู้คนมากขึ้น ทุกคนจะต้องชอบเธออย่างแน่นอน!",
  str_n29_detective_clue_desc_12 = "ซองสวยสมบูรณ์พร้อมซีลสีแดงสด...\nจดหมายฉบับนั้นดูสูงส่งและไม่เหมาะสมในสถานเลี้ยงเด็กกำพร้าแห่งนี้ในฐานะผู้อำนวยการมาดาม",
  str_n29_detective_clue_desc_13 = "คนส่งของอ้างว่าทำของหาย\nเขาอธิบายว่ามันเป็นสีขาวและอ่อนนุ่มที่เด็กๆ จะต้องชอบ\nว่ามันคืออะไรกันแน่... ชายชราคนนั้นมีความทรงจำที่ค่อนข้างเลวร้าย—เขาลืมไปเสียสนิท!",
  str_n29_detective_clue_desc_14 = "ชายหลังค่อมคนนั้นบอกว่าเขาเป็นนักลงทุนในสถานเลี้ยงเด็กกำพร้า\nดูรายชื่อเด็กในมือของเขาพิสูจน์คำพูดของเขา เด็กทุกคนที่เคยมาที่นี่ได้รับการบันทึกไว้\nเขาบอกว่าเขาลงทุนเงินจำนวนมากเพื่อให้ทุกคนมีชีวิตที่ดีที่นี่ เพื่อให้เราทุกคนมีเสื้อผ้าและอาหารกิน",
  str_n29_detective_clue_desc_15 = "Miss Childminder เครียดมากเพราะเงินเดือนเธอน้อยมาก\nแต่ดูเหมือนว่าเธอเป็นคนเดียวที่มีปัญหาเรื่องเงินในที่แห่งนี้ เธอบอกว่าแม้แต่ภารโรงก็ยังหัวเราะเยาะที่เธอน่าสงสาร...\nเธอใจดีกับทุกคนมากและเห็นได้ชัดว่าทำงานหนักมาก แล้วทำไมชีวิตของเธอถึงไม่ดีเท่าคนขี้เกียจทำความสะอาดล่ะ?\nMiss Childminder บอกว่าเป็นเพราะผู้ใหญ่มักจะผลักไสคนที่พวกเขาไม่ชอบ",
  str_n29_detective_clue_desc_16 = "มีภาพวาดสีเทียนบนเตียงของ The Wicked King\nมันเป็นภาพของเด็กคนหนึ่งนอนอยู่ในที่เก็บของมากมาย มีของสกปรกๆ ขาวๆ อยู่ข้างๆ...\nจริง ๆ แล้ว ภาพมันยุ่งเหยิงมาก นั่นคือทั้งหมดที่ Hati ทำได้",
  str_n29_detective_clue_desc_17 = "กระเป๋าเงินที่มีรูในนั้นดูเหมือนว่าใช้มานาน\nมันเบามาก แม้กระทั่งทำให้เกิดเสียงกรอบแกรบเมื่อคุณเขย่า",
  str_n29_detective_clue_desc_18 = "ภาพดินสอสีนี้อยู่บนพื้นด้านนอก\nมันเป็นภาพวาดของคนสามคน—ผู้หญิงที่กำลังร้องไห้, ผู้ชายที่โกรธเกรี้ยว และเด็กที่ถูกทุบตี",
  str_n29_detective_clue_desc_19 = "ของเล่นลูกแกะน้อยสกปรก\nมันเต็มไปด้วยโคลนและรอยแดงเข้ม",
  str_n29_detective_clue_desc_20 = "Miss Childminder กล่าวว่าคนรวยจำนวนมากจะมาดูการแสดงในวันพรุ่งนี้ พวกเขาจะรับเลี้ยงเด็กที่ทำผลงานได้ดี\nรางวัลนี้สำหรับเด็กดีเท่านั้น\nHati ช่วย Miss Childminder หากระเป๋าของเธอ และเธอบอกว่า Hati ควรจะลองแสดงบนเวทีด้วย",
  str_n29_detective_clue_desc_21 = "คนส่งของคนนั้นบอกว่าเราควรให้โอกาสคนที่ทำผิดพลาดเพื่อชดเชยเป็นการส่วนตัว\nนั่นคือความปรารถนาดีของผู้ใหญ่\nโลกของผู้ใหญ่นั้นซับซ้อน ดังนั้นพวกเขาจึงพยายามแก้ปัญหาด้วยวิธีที่สันติและมีเหตุผล เป็นสิ่งที่ดีที่สุดสำหรับทุกคน",
  str_n29_detective_clue_desc_22 = "คุณรู้หรือไม่ว่าทำไมการใช้ชีวิตในสถานเลี้ยงเด็กกำพร้าจึงมีความสุข?\nเพราะผู้ใหญ่ที่นี่รักเด็กมาก\nทุกคนทำงานที่นี่เพื่อมอบความรักให้พวกเราโดยไม่หวังสิ่งตอบแทน\nนั่นเป็นเหตุผลที่เราต้องเรียนรู้ที่จะขอบคุณ",
  str_n29_detective_clue_desc_23 = "ตุ๊กตาตัวเก่าที่พัง\nเห็นได้ชัดว่าสิ่งนี้เป็นของใคร พวกเขารักมันมาก\nเดาว่าไม่สำคัญหรอกว่าคุณรักอะไรมากแค่ไหน มันก็จะเก่าและพังลงเมื่อเวลาผ่านไปนานพอควร",
  str_n29_detective_clue_desc_24 = "สถานเลี้ยงเด็กกำพร้าจัดงานเลี้ยงทุกสิ้นเดือน เป็นหนึ่งในกิจกรรมที่สำคัญที่สุดที่นี่\nเด็กส่วนใหญ่มักจะประพฤติตัวดีในงานปาร์ตี้เหล่านี้ และพยายามทำตัวเป็นเด็กดีและเป็นที่นิยมเพื่อแสดงให้ทุกคนเห็นด้านที่ดีที่สุดของพวกเขา\n\nต้องเป็นเพราะเหตุการณ์สำคัญอีกเหตุการณ์หนึ่งเกิดขึ้นหลังจากงานเลี้ยงตอนเย็นช่วงสิ้นเดือนได้ไม่นาน นั่นคือวันรับเลี้ยงบุตรบุญธรรม เมื่อเด็กที่เลวและดีต่างก็ออกจากสถานเลี้ยงเด็กกำพร้าเพื่อไปบ้านใหม่",
  str_n29_detective_clue_desc_25 = "ฮาติต้องเริ่มซ้อมการแสดงตั้งแต่ตอนนี้เพื่อให้แน่ใจว่าเธอได้เรียนรู้ทุกบทก่อนการแสดง!\nทุกคนยุ่งกับการเตรียมงานจึงไม่มีเวลาช่วยฮาติ...\nตอนนี้ฮาติต้องไปหลังเวทีคนเดียวเพื่อหาอุปกรณ์ประกอบฉาก จากนั้นไปที่ห้องผู้อำนวยการเพื่อค้นหาสคริปต์",
  str_n29_detective_clue_desc_26 = "เช้าตรู่วันนี้ ช่างแขวนเสื้อคนนั้นเห็นภารโรงกำลังเก็บเตียงของ The Wicked King และนำสิ่งของของเขาไปที่ประตูหลังเพื่อมอบให้กับคนส่งของ\nราชาผู้ชั่วร้ายหายไปไหน?",
  str_n29_detective_clue_desc_27 = "บุคลิกเน่าเฟะ นิสัยเลวทราม แนวรุนแรงที่คาดเดาไม่ได้...\nไม่มีใครต้องการคนสารเลวแบบนั้น\nนั่นเป็นเหตุผลที่ไม่มีใครรับเลี้ยง The Wicked King เข้าใจไหม?",
  str_n29_detective_clue_desc_28 = "ราชาผู้ชั่วร้ายจากไปและฮาติเข้ามาแทนที่ในฐานะตัวละครหลัก\nคนส่งของคนนั้นบอกว่า Hati ควรใช้เวลาน้อยลงในการกังวลเกี่ยวกับ The Wicked King และมีเวลามากขึ้นในการกังวลเกี่ยวกับตัวเอง",
  str_n29_detective_clue_desc_29 = "การลงทะเบียนนี้คล้ายกับการลงทะเบียนของนักลงทุน\nข้อแตกต่างเพียงอย่างเดียวคือเครื่องหมายเหล่านี้อยู่ข้างชื่อเด็ก\nบางส่วนถูกขีดฆ่าและบางส่วนถูกขีดฆ่า\nเปิดไปที่หน้าล่าสุด และชื่อของ Hati ก็อยู่ในหน้านั้น ชื่อ The Wicked King อยู่บนนั้นด้วย\nราชาผู้ชั่วร้าย, ฮาติ, แฮงออน, สาวสวย... พวกมันทั้งหมดอยู่บนนั้น และพวกมันทั้งหมดถูกทำเครื่องหมายด้วยกากบาทสีแดงสด นั่นหมายถึงอะไร?",
  str_n29_detective_clue_desc_30 = "หนังสือสคริปต์สกปรกครึ่งหนึ่งเปื้อนหมึกสีแดงเข้ม\nหมึกมีกลิ่นคาวนิดหน่อย...แปลกดี",
  str_n29_detective_clue_desc_31 = "ขวานสั้น\nมีรอยสนิมมากมาย แต่ใบมีดขัดเงาและคมมาก\nของอันตรายแบบนี้ไม่ควรใช้เป็นอุปกรณ์ประกอบการแสดง...",
  str_n29_detective_clue_desc_32 = "ฮาติทำให้มิสไชล์ดมินเดอร์โกรธ\nMiss Childminder บอกว่า Hati ไม่ควรปฏิบัติต่อสิ่งที่เป็นอันตรายอย่างประมาทเลินเล่อ\nมีเพียงสุนัขจรจัดเท่านั้นที่หยิบจับสิ่งของอย่างไม่คิดชีวิต\nฮาติเป็นสุนัขจรจัดหรือไม่?",
  str_n29_detective_clue_desc_33 = "เด็กหญิงพูดบางอย่างอย่างจริงจังกับ Hati เกี่ยวกับวิธีที่เธอควรพยายามบอกความแตกต่างระหว่างสิ่งที่สำคัญกับสิ่งที่ไม่สำคัญ\nเราไม่ได้แสดงละครเพียงเพื่อเป็นนักแสดงตัวน้อยที่ดี คือการเป็นเด็กน่ารัก น่าเอ็นดู ฉลาด กลายเป็นเด็กที่คนอยากอุ้มกลับบ้าน\nเมื่อเทียบกับสิ่งนี้ ไม่มีอะไรสำคัญอีกแล้ว\nคำเหล่านี้ฟังดูคุ้นเคย อ๋อใช่ แม่เคยพูดเรื่องเค้กหน้าร้าน",
  str_n29_detective_fragment_name_1 = "สถานการณ์ที่บ้านเด็กกำพร้า",
  str_n29_detective_fragment_name_2 = "การมาของ The Brat",
  str_n29_detective_fragment_name_3 = "สถานเลี้ยงเด็กกำพร้าแห่งความรัก",
  str_n29_detective_fragment_name_4 = "งานเลี้ยงเย็นพิเศษ",
  str_n29_detective_fragment_name_5 = "ที่อยู่ของราชาผู้ชั่วร้าย",
  str_n29_detective_fragment_name_6 = "ฮาติ เจ้าสารเลว",
  str_n29_detective_fragment_name_7 = "มอนสเตอร์ที่แท้จริง",
  str_n29_detective_fragment_desc_1 = "สถานเลี้ยงเด็กกำพร้าแห่งนี้เป็นสถานที่สำหรับเด็กจรจัด\nมันไม่ใหญ่เป็นพิเศษและสิ่งอำนวยความสะดวกต่างๆ อยู่ในสภาพโกโรโกโส แต่ Miss Childminder ก็ดูแลพวกเราอย่างดีที่สุด\nมีทั้งคนดีและไม่ดีทั้งเด็กและผู้ใหญ่ แม่ของฮาติเคยบอกว่าโลกภายนอกก็เป็นแบบนี้เช่นกัน และฮาติต้องเรียนรู้ที่จะปรับตัวให้เข้ากับมัน",
  str_n29_detective_fragment_desc_2 = "ทุกคนเกลียด The Wicked King\nเขาก้าวร้าว รุงรัง และชอบรังแกทุกคน\nแต่ไม่มีใครรบกวนเขามากเกินไป นั่นเป็นเพราะเด็กเลวจะถูกส่งไปทุกสิ้นเดือน เด็กที่ดีเท่านั้นที่จะได้อยู่ในสถานเลี้ยงเด็กกำพร้าและถูกส่งไปยังครอบครัวที่ดี",
  str_n29_detective_fragment_desc_3 = "ผู้ใหญ่ใจดีในการมอบหมายและให้ความร่วมมือ\nในสถานเลี้ยงเด็กกำพร้าแห่งนี้ บางคนมีหน้าที่ในการลงทุน บางคนให้ความรักแก่เรา และบางคนหาเงินในช่วงเวลาที่สิ้นหวัง\nอย่างไรก็ตาม ดูเหมือนว่าคนที่รับผิดชอบในการให้ความรักแก่เราเท่านั้นที่จะถูกผู้ใหญ่คนอื่นๆ วิพากษ์วิจารณ์ และชีวิตของเธอก็กลายเป็นเรื่องน่าสังเวช",
  str_n29_detective_fragment_desc_4 = "ทุกสิ้นเดือน สถานเลี้ยงเด็กกำพร้าจะจัดงานพิเศษ—งานเลี้ยงตอนเย็น\nในงานปาร์ตี้ เด็กๆ จะแสดงให้กับผู้ใหญ่บางคนที่พวกเขาไม่เคยเห็นมาก่อน เด็กที่ทำผลงานได้ดีที่สุดจะรับเลี้ยงโดยครอบครัวที่ร่ำรวย\nการแสดงในเดือนนี้เป็นการแสดงละครเวที The Wicked King รับบทเป็นฮีโร่ สาวสวยรับบทเป็นเจ้าหญิง ส่วน Hang-on และ Miss Childminder รับบทเป็นชาวบ้าน เด็กสาวแสนดีดึงความสนใจของ The Wicked King ไปจนหมด และนั่นทำให้เขาคลั่งไคล้จริงๆ",
  str_n29_detective_fragment_desc_5 = "ก่อนที่เขาจะหายตัวไป The Wicked King อิจฉาหญิงสาวแสนดีและกำลังจะทำอะไรไม่ดีกับเธอ เขาขโมยตุ๊กตาของเธอและแอบเข้าไปในรถม้าของคนส่งของ แต่หลังจากเห็นสิ่งที่เขาเห็นในที่สุดเขาก็เปลี่ยนใจ หลังจากวิ่งหนีอย่างเร่งรีบ เขาก็ดึงสิ่งที่เขาเห็น\nเมื่อวานนี้ คนส่งของบอกว่าเขาจะแก้ปัญหาเป็นการส่วนตัวเพื่อหลีกเลี่ยงความอับอาย วันนี้ราชาผู้ชั่วร้ายหายตัวไป\nคนส่งของบอกว่าเขาเป็นลูกบุญธรรม แต่เมื่อดูหนังสือสคริปต์สกปรกนี้ บางทีภารโรงอาจพูดถูก...",
  str_n29_detective_fragment_desc_6 = "ตอนแรกคนไม่ชอบฮาติ\nฮาติพยายามอย่างมากที่จะทำให้ทุกคนมีความสุข\nแต่ถึงตอนนี้...ก็ยังมีคนไม่ชอบเธออยู่",
  str_n29_detective_fragment_desc_7 = "พวกเขาจัดการกับเด็กเลวอย่างลับๆ\nผู้ใหญ่ที่ใส่ใจแต่เรื่องเงินกำลังหาประโยชน์จากมัน\nเด็กเจ้าปัญหาจะถูกจัดการโดยเร็วที่สุด หมายความว่าวันเวลาของ Hati จะถูกนับ",
  str_n29_detective_end_name_1 = "ลาก่อนเจ้าเปี๊ยก",
  str_n29_detective_end_name_2 = "ลาก่อนฝันร้าย",
  str_n29_detective_end_desc_1 = "โจร หมาจรจัด อสูรน้อย...\nไม่มีใครเล่นกับคุณ ไม่มีใครชอบคุณ.\nหายไปจากที่นี่เร็วเข้า!",
  str_n29_detective_end_desc_2 = "วิ่งหนี\nอย่างอิสระ หันหน้าเข้าหากันเสมอ\nอย่ามองย้อนกลับไป",
  str_n29_detective_point_lockname_3 = "เด็กหญิง",
  str_n29_detective_point_lockname_4 = "เด็กขี้เซา",
  str_n29_detective_point_lockname_5 = "เด็กป่า",
  str_n29_detective_point_lockname_6 = "หญิงชรา",
  str_n29_detective_point_lockname_7 = "คนอ้วน",
  str_n29_detective_point_lockname_8 = "สุภาพบุรุษหลังค่อม",
  str_n29_detective_point_lockname_9 = "สถานที่ที่จะนอนหลับ",
  str_n29_detective_point_lockname_10 = "สนามหญ้า",
  str_n29_detective_point_lockname_11 = "หลังม่าน",
  str_n29_detective_point_lockname_12 = "ห้องที่แตกต่างกัน",
  str_n29_detective_point_name_1 = "ผู้ดูแลเด็ก",
  str_n29_detective_point_name_2 = "ทำความสะอาด",
  str_n29_detective_point_name_3 = "สาวใจดี",
  str_n29_detective_point_name_4 = "ลูกแกะ",
  str_n29_detective_point_name_5 = "ราชาผู้ชั่วร้าย",
  str_n29_detective_point_name_6 = "คณบดีเก่า",
  str_n29_detective_point_name_7 = "คูเรียร์",
  str_n29_detective_point_name_8 = "นักลงทุน",
  str_n29_detective_point_name_9 = "หอพัก",
  str_n29_detective_point_name_10 = "เดอะยาร์ด",
  str_n29_detective_point_name_11 = "หลังเวที",
  str_n29_detective_point_name_12 = "สำนักงานผู้อำนวยการ",
  str_n29_detective_point_lockdesc_3 = "เด็กอีกคนในห้อง\n\n<color=#902121>ฮาติยังไม่อยากคุยกับเธอตอนนี้</color>",
  str_n29_detective_point_lockdesc_4 = "เขามักจะเดินตามหลังเด็กที่แกร่งกว่าด้วยรอยยิ้มที่น่ารังเกียจ\n\n<color=#902121>ฮาติไม่อยากคุยกับเขา ถ้าไม่เป็นไร</color>",
  str_n29_detective_point_lockdesc_5 = "เด็กที่มีเสียงดังซึ่งดูก้าวร้าวมาก\n\n<color=#902121>อยู่ห่างจากเขาถ้าเป็นไปได้</color>",
  str_n29_detective_point_lockdesc_6 = "หญิงชราในชุดดำมองฮาติด้วยสายตาไม่พอใจเสมอ\n\n<color=#902121>คุณไม่ควรรบกวนเธอถ้าไม่เป็นไร</color>",
  str_n29_detective_point_lockdesc_7 = "ไอ้อ้วนนั่น รถม้าข้างเขาเป็นของเขาหรือเปล่า?\n\n<color=#902121>อย่ารบกวนเขาเว้นแต่คุณจะต้องการจริงๆ</color>",
  str_n29_detective_point_lockdesc_8 = "ชายชราหลังค่อมตัวน้อยคนนี้ดูมีฐานะดีทีเดียว\nด้วยเหตุผลบางอย่าง ฮาติไม่ชอบเขา\n\n<color=#902121>ฮาติไม่อยากคุยกับเขาถ้านั่นไม่ใช่ปัญหา</color>",
  str_n29_detective_point_lockdesc_9 = "หทัยเคยนอนกอดแม่\nแม่...\n\n<color=#902121>ฮาติไม่อยู่ในอารมณ์ที่จะสำรวจที่นี่ในขณะนี้</color>",
  str_n29_detective_point_lockdesc_10 = "ฮาติไม่เคยได้รับอนุญาตให้ออกไปเล่นตอนที่เธออาศัยอยู่กับแม่\nกลิ้งบนสนามหญ้ารู้สึกดีไหม?\nแต่ลูกคนอื่นไม่ได้ออกไปเล่น...\n\n<color=#902121>ฮาติเป็นเด็กดีเชื่อฟัง กลับมาที่นี่เมื่อคุณต้องการเท่านั้น</color>",
  str_n29_detective_point_lockdesc_11 = "อะไรอยู่หลังม่าน?\nฉันอยากจะเปิดผ้าคลุมออกและดูว่ามีอะไรอยู่ในนั้นจริงๆ\nแต่ผู้ใหญ่บอกว่าห้ามเล่นที่นี่...\n\n<color=#902121>ฮาติเป็นเด็กดีเชื่อฟัง กลับมาที่นี่เมื่อคุณต้องการเท่านั้น</color>",
  str_n29_detective_point_lockdesc_12 = "ประตูนี้ดูสวยงามมาก มันหนามากและแตกต่างจากที่อื่น\nแต่เจ้าของไม่ชอบให้ใครเข้ามาโดยไม่ได้รับอนุญาต...\n\n<color=#902121>ฮาติเป็นเด็กดีเชื่อฟัง กลับมาที่นี่เมื่อคุณต้องการเท่านั้น</color>",
  str_n29_detective_point_desc_1 = "ใจดี Miss Childminder\nมือของเธอบางและหยาบมาก เหมือนมือของแม่\nในบรรดาผู้ใหญ่ทั้งหมด เธอเป็นคนที่ฮาติไว้วางใจมากที่สุด\nเมื่อใดก็ตามที่มี <color=#902121>บางอย่างที่เธอไม่กล้าถามใคร เธอสามารถถามเธอได้ตลอดเวลา</color>",
  str_n29_detective_point_desc_2 = "ภารโรงที่ชอบเดินเล่น\nเธอไม่ชอบเด็ก และเธอมักเยาะเย้ยฮาติเสมอ เธอมันเลว!\nอย่างไรก็ตาม เธอเป็นคนเดียวที่กล้าบอกฮาติ <color=#902121>ความลับที่ผู้ใหญ่คนอื่นไม่ยอมบอก</color>",
  str_n29_detective_point_desc_3 = "ผู้หญิงที่พูดเสียงเบาและชอบหัวเราะ\nฮาติรู้สึกว่าเธออาจจะทำได้ <color=#902121>เป็นเพื่อนกับเธอ...</color>\nดูเหมือนจะมีลางร้ายซ่อนอยู่ในรอยยิ้มของเธอเสมอ แต่ <color=#902121>จะช่วยอะไรเธอได้บ้าง</color>",
  str_n29_detective_point_desc_4 = "ขี้ข้าของ Wicked King\nอย่างไรก็ตาม, <color=#902121>ราชาผู้ชั่วร้ายไม่ชอบเขา...</color>\n<color=#902121>ทำไมเขาดูพอใจที่ได้เดินตาม The Wicked King ไปรอบๆ?</color>",
  str_n29_detective_point_desc_5 = "ทุกคนเกลียด The Wicked King\nเขาเสมอ <color=#902121>ชอบแกล้งคน</color>แล้วทำไมใครๆถึงชอบเขา?\n<color=#902121>หากไม่มีเพื่อนก็เป็นไปไม่ได้ที่จะเปิดใจให้ใคร</color>\nบางทีถ้าคุณต้องการ <color=#902121>โทรหาเขาเขาจะคุยกับคุณ</color>",
  str_n29_detective_point_desc_6 = "ผู้อำนวยการสถานเลี้ยงเด็กกำพร้าคนเก่าดูราวกับว่าเธอ <color=#902121>ไม่พอใจทุกอย่างอย่างแน่นอน</color>\nฮาติไม่ชอบเวลาที่เธอจ้องมองเธอ <color=#902121>หากเพียงเธอไม่อยู่ที่นี่</color>",
  str_n29_detective_point_desc_7 = "คนส่งของที่บ้านเด็กกำพร้าชอบหัวเราะเสียงดัง\nเขาดูเหมือนจะ <color=#902121>สนุกกับการอยู่ใกล้เด็กๆ</color> และสนทนากับฮาติในเรื่องต่างๆ\nของเขา <color=#902121>การขนส่ง</color> อยากรู้อยากเห็นมากจริงๆ มีอะไรอยู่ข้างใน?",
  str_n29_detective_point_desc_8 = "นักลงทุนในสถานเลี้ยงเด็กกำพร้าที่เป็น <color=#902121>จ้องมองไปที่ฮาติเสมอ</color>\nฮาติไม่ชอบเขา",
  str_n29_detective_point_desc_9 = "นี่คือที่ที่ Hati และเด็กคนอื่นๆ นอนและเล่น\n<color=#902121>ความลับของพวกเขา</color> มักจะซ่อนอยู่กับพวกเขาภายใต้ผ้าคลุม\n<color=#902121>นางสาวเด็กผู้ดูแล</color> ก็ชอบที่จะอยู่ที่นี่ บางครั้งเธอนั่งที่นี่และถอนหายใจ",
  str_n29_detective_point_desc_10 = "พวกผู้ใหญ่บอกว่าอากาศข้างนอกไม่ดี เราจึงไม่อนุญาตให้ออกไปเล่น แต่ก็มีเด็กที่ไม่เชื่อฟังอยู่เสมอที่<color=#902121>แอบออกไป</color> <color=#902121>Mr. นักลงทุน</color> ก็มาด้วย... ฮาติไม่ชอบเขา",
  str_n29_detective_point_desc_11 = "ไอ ไอ... ที่นี่ฝุ่นเยอะมาก\nพื้นที่หลังเวทีเต็มไปด้วยอุปกรณ์ประกอบการแสดงที่เด็กๆ ทำขึ้น อาจจะมีก็ได้ <color=#902121>สมบัติ</color> ซ่อนอยู่ที่นี่?",
  str_n29_detective_point_desc_12 = "Hati ไม่เคยเห็นห้องที่สวยงามเช่นนี้มาก่อน แต่ไม่มีหน้าต่างเหมือนที่บ้านของ Hati!\nตอนนี้ไม่มีใครอยู่ที่นี่ ดังนั้นหากคุณลองดูที่ <color=#902121>ความลับของผู้อำนวยการเก่า</color>, จะมีใครรู้ไหม?",
  str_n29_detective_character_random_1 = "เกิดอะไรขึ้น? คุณหิวไหม?",
  str_n29_detective_character_random_2 = "ถ้ามีอะไรที่สำคัญอย่าลืมบอกฉัน",
  str_n29_detective_character_random_3 = "ไอ ไอ... ไม่เป็นไร ไม่ต้องห่วงฉัน",
  str_n29_detective_character_random_4 = "เลิกยุ่งกับฉันสักที",
