  str_n29_detective_character_random_12 = "สถานเลี้ยงเด็กกำพร้าเป็นสถานที่ที่ดีที่สุดในโลก",
  str_n29_detective_character_random_13 = "ข้าคือ The Glorious King พวกเจ้าต้องทำตามที่ข้าบอก!",
  str_n29_detective_character_random_14 = "ฉันเป็นเด็กที่ดังที่สุดที่นี่ ทุกคนควรทำตามที่ฉันบอก!",
  str_n29_detective_character_random_15 = "มอบของเล่นของคุณและหลงทาง!",
  str_n29_detective_character_random_16 = "... ฉันช่วยคุณได้ไหม?",
