  str_n29_detective_character_mission_8 = "กรอกคำอธิบายที่สามของคุณ",
  str_n29_detective_character_mission_desc_1 = "ระมัดระวัง. เมื่อวิ่งหนีจากสิ่งที่เราต้องเผชิญ เรามักจะจมดิ่งสู่ความสิ้นหวัง",
  str_n29_detective_character_mission_desc_2 = "แสงแรกของแสงแดดส่องผ่านยามค่ำคืนอย่างเงียบ ๆ ได้เวลาตื่นแล้ว ฟลัฟฟี่",
  str_n29_detective_character_mission_desc_3 = "ความอยากรู้อยากเห็นในระดับหนึ่งทำให้คุณดูน่ารัก",
  str_n29_detective_character_mission_desc_4 = "อาจมีเพียงเส้นบางๆ ระหว่างการสอบถามและการหยาบคาย",
  str_n29_detective_character_mission_desc_5 = "ไม่ควรดึงผ้าม่านทั้งหมด",
  str_n29_detective_character_mission_desc_6 = "เด็กน้อยที่สดใส เป็นที่รักของทุกคน ทุกคนภูมิใจในตัวคุณมาก",
  str_n29_detective_character_mission_desc_7 = "ความฉลาดของคุณเริ่มทำให้ผู้ใหญ่อับอาย ถึงเวลาที่คุณเรียนรู้ที่จะเล่นเป็นใบ้",
  str_n29_detective_character_mission_desc_8 = "ไม่ใช่ทุกคำถามควรมีคำตอบ",
