  str_n29_detective_character_mission_name_2 = "ปลดล็อกอำลาตอนจบฝันร้าย",
  str_n29_detective_character_mission_name_3 = "เข้าถึงความลึกของความฝัน 30%",
  str_n29_detective_character_mission_name_4 = "เข้าถึงความลึกของความฝัน 60%",
  str_n29_detective_character_mission_name_5 = "เข้าถึงความลึกของความฝัน 100%",
  str_n29_detective_character_mission_name_6 = "กรอกคำอธิบายแรกของคุณ",
  str_n29_detective_character_mission_name_7 = "กรอกคำอธิบายที่สองของคุณ",
  str_n29_detective_character_mission_name_8 = "กรอกคำอธิบายที่สามของคุณ",
  str_n29_detective_question_1 = "สถานเลี้ยงเด็กกำพร้าเป็นสถานที่แบบไหน? คนที่อยู่กับเราคือใคร? พวกเขาเป็นคนดีทั้งหมดหรือไม่?",
  str_n29_detective_question_2 = "เด็ก ๆ เกลียดใครมากที่สุด? ทุกคนมีความคิดเห็นอย่างไรกับเรื่องนี้?",
  str_n29_detective_question_3 = "สิ่งที่ผู้ใหญ่พูดเกี่ยวกับเงินดูเหมือนจะแตกต่างออกไปบ้าง ... เกิดอะไรขึ้น?",
  str_n29_detective_question_4 = "ทุกคนพูดถึงงานปาร์ตี้ราวกับว่าพวกเขาตื่นเต้นกับมัน พวกเขาหมายถึงปาร์ตี้ประเภทไหน?",
